def twoEditWords(queries, dictionary):
    result = []
    for q in queries:
        found = False
        for d in dictionary:
            # Early skip if already found
            diff = 0
            for qc, dc in zip(q, d):
                if qc != dc:
                    diff += 1
                    if diff > 2:
                        break
            if diff <= 2:
                result.append(q)
                found = True
                break
    return result
